// BEM FKIP Progresio — Shared JS
const LOGO_BEM = 'data:image/png;base64,';
const LOGO_KAB = 'data:image/png;base64,';

// Inject navbar
function buildNavbar(activePage) {
  const pages = [
    { href: 'index.html',       label: 'Beranda' },
    { href: 'tentang.html',     label: 'Tentang' },
    { href: 'kegiatan.html',    label: 'Kegiatan' },
    { href: 'dokumentasi.html', label: 'Dokumentasi' },
    { href: 'berita.html',      label: 'Berita' },
    { href: 'kontak.html',      label: 'Kontak' },
  ];
  const links = pages.map(p =>
    '<a href="' + p.href + '"' + (p.href === activePage ? ' class="active"' : '') + '>' + p.label + '</a>'
  ).join('');

  return '<nav class="navbar"><div class="nav-inner">'
    + '<a class="nav-brand" href="index.html">'
    + '<img src="' + LOGO_BEM + '" alt="BEM FKIP"/>'
    + '<img src="' + LOGO_KAB + '" alt="Progresio" style="margin-left:4px"/>'
    + '<div class="nav-brand-text"><div class="org">BEM FKIP</div><div class="kabinet">Kabinet Progresio</div></div>'
    + '</a>'
    + '<div class="nav-links" id="navLinks">' + links + '</div>'
    + '<button class="nav-toggle" onclick="document.getElementById(\'navLinks\').classList.toggle(\'open\')" aria-label="Menu">'
    + '<span></span><span></span><span></span>'
    + '</button>'
    + '</div></nav>';
}

function buildFooter() {
  return '<footer><div class="footer-inner">'
    + '<div class="footer-grid">'
    + '<div class="footer-brand">'
    + '<img src="' + LOGO_BEM + '" alt="BEM FKIP"/>'
    + '<p><strong style="color:#f5c800">BEM FKIP — Kabinet Progresio</strong><br>'
    + 'Universitas Nahdlatul Ulama Cirebon<br>'
    + 'Bergerak. Berkembang. Berdampak.</p>'
    + '</div>'
    + '<div class="footer-col"><h4>Navigasi</h4>'
    + '<a href="index.html">Beranda</a>'
    + '<a href="tentang.html">Tentang Kami</a>'
    + '<a href="kegiatan.html">Kegiatan</a>'
    + '<a href="dokumentasi.html">Dokumentasi</a>'
    + '<a href="berita.html">Berita</a>'
    + '<a href="kontak.html">Kontak</a>'
    + '</div>'
    + '<div class="footer-col"><h4>Kontak</h4>'
    + '<a href="mailto:bemfkip@unucirebon.ac.id">bemfkip@unucirebon.ac.id</a>'
    + '<a href="#">Instagram: @bemfkip_unuc</a>'
    + '<a href="#">FKIP — Universitas Nahdlatul Ulama Cirebon</a>'
    + '</div>'
    + '</div>'
    + '<div class="footer-bottom">'
    + '<span>&copy; 2025 BEM FKIP Kabinet Progresio — Universitas Nahdlatul Ulama Cirebon</span>'
    + '<span>Made with dedication</span>'
    + '</div>'
    + '</div></footer>';
}

document.addEventListener('DOMContentLoaded', function() {
  const activePage = window.location.pathname.split('/').pop() || 'index.html';
  const navEl = document.getElementById('navbar-placeholder');
  const footEl = document.getElementById('footer-placeholder');
  if (navEl) navEl.outerHTML = buildNavbar(activePage);
  if (footEl) footEl.outerHTML = buildFooter();
});
